private void открытьToolStripMenuItem_Click(object sender, EventArgs e)
{
    OpenFileDialog open = new OpenFileDialog();   // новый объект open
    open.Title = "Open";                          // заголовок окна
    open.Filter = "All Files|*.*";                // все типы файлов
    try                                           // обработка исключений
    {
        if (open.ShowDialog() == System.Windows.Forms.DialogResult.OK)
        {
            axWindowsMediaPlayer1.URL = open.FileName;   // файл для проигрывания
        }
    }
    catch (ArgumentException ex)                  // если обнаружится ошибка
    {
        MessageBox.Show(ex.Message.ToString(), "Error",
            MessageBoxButtons.OK, MessageBoxIcon.Error);
    }
    catch (Exception ex) { }
}

